export type Keg = {
    readonly id: number;
    beverage: Beverage;
    /**
     * Keg container type, used to initialize keg's full volume
     *
     * * `mini` - Mini Keg (5 L)
     * * `corny-2_5-gal` - Corny Keg (2.5 gal)
     * * `corny-3-gal` - Corny Keg (3.0 gal)
     * * `corny` - Corny Keg (5 gal)
     * * `sixth` - Sixth Barrel (5.17 gal)
     * * `euro-30-liter` - European DIN (30 L)
     * * `euro-half` - European Half Barrel (50 L)
     * * `quarter` - Quarter Barrel (7.75 gal)
     * * `euro` - European Full Barrel (100 L)
     * * `half-barrel` - Half Barrel (15.5 gal)
     * * `other` - Other
     */
    keg_type?: KegTypeEnum;
    /**
     * Computed served volume.
     */
    readonly served_volume_ml: number;
    /**
     * Full volume of this Keg; usually set automatically from keg_type.
     */
    full_volume_ml?: number;
    /**
     * Time the Keg was first tapped.
     */
    readonly start_time: string;
    /**
     * Time the Keg was finished or disconnected.
     */
    readonly end_time: string;
    /**
     * Current keg state.
     *
     * * `available` - Available
     * * `on_tap` - On tap
     * * `finished` - Finished
     */
    status: KegStatusEnum;
    /**
     * User-visible description of the Keg.
     */
    description?: string | null;
    /**
     * Amount of beverage poured without an associated Drink.
     */
    readonly spilled_ml: number;
    /**
     * Private notes about this keg, viewable only by admins.
     */
    notes?: string | null;
    readonly illustration: string;
    readonly illustration_thumbnail: string;
    readonly stats: unknown;
};

