export type Stats = {
    time?: string;
    stats: unknown;
    readonly drink_id: number;
    readonly user_id: number | null;
    readonly keg_id: number | null;
    readonly session_id: number | null;
};

export type SystemEvent = {
    readonly id: number;
    /**
     * Type of event.
     *
     * * `drink_poured` - Drink poured
     * * `session_started` - Session started
     * * `session_joined` - User joined session
     * * `keg_tapped` - Keg tapped
     * * `keg_volume_low` - Keg volume low
     * * `keg_ended` - Keg ended
     */
    kind: SystemEventKindEnum;
    /**
     * Time of the event.
     */
    time: string;
    drink: Drink;
    user: User;
    keg: Keg;
    session: DrinkingSession;
};

/**
 * * `drink_poured` - Drink poured
 * * `session_started` - Session started
 * * `session_joined` - User joined session
 * * `keg_tapped` - Keg tapped
 * * `keg_volume_low` - Keg volume low
 * * `keg_ended` - Keg ended
 */
export type SystemEventKindEnum = 'drink_poured' | 'session_started' | 'session_joined' | 'keg_tapped' | 'keg_volume_low' | 'keg_ended';

/**
 * A summarized system status status, with the most common "current status" data.
 */
export type SystemStatus = {
    site: KegbotSite;
    taps: Array<KegTap>;
    events: Array<SystemEvent>;
};

export type TapAttachKegRequestRequest = {
    keg_id: number;
};

export type TapConnectMeterRequestRequest = {
    meter_id: number | null;
};

export type TapConnectThermoRequestRequest = {
    thermo_sensor_id: number | null;
};

export type TapConnectToggleRequestRequest = {
    toggle_id: number | null;
};

export type TapRecordDrinkRequestRequest = {
    volume_ml: number;
    username?: string;
    pour_time?: string | null;
    duration?: number;
    shout?: string;
    spilled?: boolean;
};

/**
 * * `f` - Fahrenheit
 * * `c` - Celsius
 */
export type TemperatureDisplayUnitsEnum = 'f' | 'c';

export type ThermoSensor = {
    readonly id: number;
    raw_name: string;
    nice_name: string;
};

export type ThermoSensorRequest = {
    raw_name: string;
    nice_name: string;
};

export type Thermolog = {
    time: string;
    temp: number;
    readonly sensor_id: number;
};

